/**
 * Minimal i18n: thirteen languages — English (default), Japanese,
 * Simplified Chinese, Korean, Spanish, Turkish, Persian, Indonesian,
 * Vietnamese, Portuguese, Dutch, Hindi, French. Plain everyday words only;
 * no jargon on screen, in every language.
 *
 * Persian (fa) is a right-to-left language: when it is the active
 * language the whole layout mirrors (see src/lib/rtl.ts, which
 * drives I18nManager from langIsRtl below). All other languages
 * are left-to-right.
 *
 * The current language lives in a module-level variable (set by
 * AppContext) so plain library code can translate too, mirroring
 * the GuppyWallet pattern.
 */
export type Lang =
  | 'en' | 'ja' | 'zh' | 'ko' | 'es' | 'tr' | 'fa'
  | 'id' | 'vi' | 'pt' | 'nl' | 'hi' | 'fr';

export const LANGS: { code: Lang; label: string }[] = [
  { code: 'en', label: 'English' },
  { code: 'ja', label: '日本語' },
  { code: 'zh', label: '简体中文' },
  { code: 'ko', label: '한국어' },
  { code: 'es', label: 'Español' },
  { code: 'tr', label: 'Türkçe' },
  { code: 'fa', label: 'فارسی' },
  { code: 'id', label: 'Bahasa Indonesia' },
  { code: 'vi', label: 'Tiếng Việt' },
  { code: 'pt', label: 'Português' },
  { code: 'nl', label: 'Nederlands' },
  { code: 'hi', label: 'हिन्दी' },
  { code: 'fr', label: 'Français' },
];

export function isLang(v: unknown): v is Lang {
  return (
    v === 'en' || v === 'ja' || v === 'zh' || v === 'ko' || v === 'es' ||
    v === 'tr' || v === 'fa' || v === 'id' || v === 'vi' || v === 'pt' ||
    v === 'nl' || v === 'hi' || v === 'fr'
  );
}

/** True for languages written right-to-left (only Persian). */
export function langIsRtl(l: Lang): boolean {
  return l === 'fa';
}

/** BCP-47 locale per language, for date formatting. */
export const LOCALES: Record<Lang, string> = {
  en: 'en-US',
  ja: 'ja-JP',
  zh: 'zh-CN',
  ko: 'ko-KR',
  es: 'es-ES',
  tr: 'tr-TR',
  fa: 'fa-IR',
  id: 'id-ID',
  vi: 'vi-VN',
  pt: 'pt-BR',
  nl: 'nl-NL',
  hi: 'hi-IN',
  fr: 'fr-FR',
};

let current: Lang = 'en';
export function setLang(l: Lang): void {
  current = l;
}
export function getLang(): Lang {
  return current;
}

